#!/usr/bin/env node
/**
 * DakFlare desktop CLI.
 *
 * Two credentials, deliberately never mixed:
 *
 *   1. Cloudflare account  — obtained by `wrangler login` (OAuth). Used only to create
 *      resources, deploy, and set the Worker secret. This CLI never stores it; Wrangler owns it.
 *   2. Deployment admin    — the `ADMIN_TOKEN` Worker secret. Used to call `/v1/admin/*` on one
 *      deployment. Generated by `init`, stored in the local config (0600), never printed.
 *
 * A user therefore never has to copy a token out of a dashboard, and `doctor`/`pair`/`send`
 * work without the Cloudflare account being authenticated at all.
 *
 * Zero dependencies. Node 20+ (needs global fetch and node:crypto).
 */

import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, '..');
const WORKER_DIR = path.join(REPO_ROOT, 'worker');

const CONFIG_DIR = path.join(os.homedir(), '.config', 'dakflare');
const CONFIG_FILE = path.join(CONFIG_DIR, 'config.json');

/* ───────────────────────────── config ───────────────────────────── */

function loadConfig() {
  try {
    return JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8'));
  } catch {
    return null;
  }
}

function saveConfig(cfg) {
  fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
  fs.writeFileSync(CONFIG_FILE, JSON.stringify(cfg, null, 2), { mode: 0o600 });
  // writeFileSync only applies `mode` on creation; enforce it either way.
  try { fs.chmodSync(CONFIG_FILE, 0o600); } catch { /* best effort on odd filesystems */ }
}

function requireConfig() {
  const cfg = loadConfig();
  if (!cfg?.url || !cfg?.token) {
    fail(
      'no deployment configured.\n' +
      '  run `dakflare init` to install one, or\n' +
      '  run `dakflare use <worker-url> --token <admin-token>` to point at an existing one.'
    );
  }
  return cfg;
}

/* ───────────────────────────── helpers ──────────────────────────── */

const out = (s = '') => process.stdout.write(`${s}\n`);
const ok = (s) => out(`  ✓ ${s}`);
const warn = (s) => out(`  ! ${s}`);

function fail(message, code = 1) {
  process.stderr.write(`\n  ✗ ${message}\n\n`);
  process.exit(code);
}

function section(title) {
  out('');
  out(title);
  out('─'.repeat(Math.min(title.length, 60)));
}

function mask(token) {
  return token ? `${token.slice(0, 4)}…${token.slice(-4)}` : '(none)';
}

function parseFlags(argv) {
  const flags = {};
  const rest = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { flags[key] = next; i++; }
      else flags[key] = true;
    } else rest.push(a);
  }
  return { flags, rest };
}

/** Run wrangler in the worker directory. Returns {status, stdout, stderr}. */
function wrangler(args, { input, quiet = false } = {}) {
  const res = spawnSync('npx', ['wrangler', ...args], {
    cwd: WORKER_DIR,
    input,
    encoding: 'utf8',
    env: process.env,
    stdio: ['pipe', 'pipe', 'pipe'],
  });
  if (!quiet && res.status !== 0) {
    const detail = (res.stderr || res.stdout || '').trim().split('\n').slice(-6).join('\n');
    fail(`wrangler ${args.join(' ')} failed:\n${detail}`);
  }
  return res;
}

/** Run cf (the Cloudflare CLI) in the worker directory. */
function cf(args, { input, quiet = false } = {}) {
  const res = spawnSync('npx', ['cf', ...args], {
    cwd: WORKER_DIR,
    input,
    encoding: 'utf8',
    env: process.env,
    stdio: ['pipe', 'pipe', 'pipe'],
  });
  if (!quiet && res.status !== 0) {
    const detail = (res.stderr || res.stdout || '').trim().split('\n').slice(-6).join('\n');
    fail(`cf ${args.join(' ')} failed:\n${detail}`);
  }
  return res;
}

function wranglerLoggedIn() {
  const res = spawnSync('npx', ['wrangler', 'whoami'], { cwd: WORKER_DIR, encoding: 'utf8' });
  return /logged in/i.test(`${res.stdout}${res.stderr}`);
}

async function api(cfg, method, pathname, body) {
  let res;
  try {
    res = await fetch(`${cfg.url.replace(/\/$/, '')}${pathname}`, {
      method,
      headers: {
        Authorization: `Bearer ${cfg.token}`,
        ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch (error) {
    // A transport failure is not an HTTP status; say so instead of leaking `TypeError: fetch failed`.
    throw new Error(
      `network error reaching ${cfg.url}${pathname} — ${error?.message ?? error}\n` +
      '  check the URL, your connection, and (if you put Access in front) your service token.'
    );
  }
  const text = await res.text();
  let data = null;
  try { data = JSON.parse(text); } catch { data = { raw: text.slice(0, 300) }; }
  return { status: res.status, data };
}

/* ───────────────────────────── commands ─────────────────────────── */

async function cmdInit(argv) {
  const { flags } = parseFlags(argv);

  section('DakFlare install');
  if (!fs.existsSync(path.join(WORKER_DIR, 'wrangler.toml'))) {
    fail('worker/wrangler.toml not found — run this from a checkout of the DakFlare repo.');
  }

  // 1. Cloudflare account plane (OAuth, owned by Wrangler).
  if (!wranglerLoggedIn()) {
    fail(
      'not authenticated with Cloudflare.\n' +
      '  run `npx wrangler login` first — the CLI never stores your Cloudflare credentials itself.'
    );
  }
  ok('Cloudflare account authenticated (wrangler OAuth)');

  // 2. Deployment admin plane: generate, never print.
  const token = typeof flags.token === 'string' && flags.token.length >= 32
    ? flags.token
    : crypto.randomBytes(32).toString('hex');
  ok(`admin token ${flags.token ? 'supplied' : 'generated'} (${mask(token)})`);

  // 3. Deploy. Prefer `cf` when the project has been migrated to cloudflare.config.ts;
  //    fall back to Wrangler otherwise. Both target the same Worker name and bindings.
  out('');
  const useCf = fs.existsSync(path.join(WORKER_DIR, 'cloudflare.config.ts'));
  out(useCf ? '  deploying with cf (cloudflare.config.ts)…' : '  deploying with wrangler (wrangler.toml)…');
  const deploy = useCf ? cf(['deploy'], { quiet: true }) : wrangler(['deploy'], { quiet: true });
  if (deploy.status !== 0) {
    const tail = `${deploy.stderr || ''}${deploy.stdout || ''}`.trim().split('\n').slice(-8).join('\n');
    fail(`deploy failed:\n${tail}`);
  }

  const urls = [...`${deploy.stdout}${deploy.stderr}`.matchAll(/https:\/\/[^\s]+\.workers\.dev/g)]
    .map((m) => m[0]);
  const url = typeof flags.url === 'string' ? flags.url : urls[urls.length - 1];
  if (!url) {
    warn('could not detect the deployment URL from wrangler output');
    out('  find it with `npx wrangler deployments status`, then:');
    out('    dakflare use <worker-url> --token <admin-token>');
  } else {
    ok(`deployed → ${url}`);
  }

  // 4. Set the Worker secret. `cf` cannot set a single secret yet (its own migration guide
  //    says to use `npx wrangler`), so this step stays on Wrangler regardless of the deploy path.
  out('');
  out('  setting ADMIN_TOKEN secret (wrangler — cf cannot set single secrets yet)…');
  wrangler(['secret', 'put', 'ADMIN_TOKEN', '--name', 'dakflare-worker'], { input: token });

  // 5. Persist locally.
  if (url) {
    saveConfig({ url, token, installedAt: new Date().toISOString() });
    ok(`saved ${CONFIG_FILE} (0600)`);
  }

  section('Next');
  out('  dakflare doctor      check the deployment is healthy');
  out('  dakflare pair        mint a pairing code for the Android app');
  out('');
  out('  Optional: `npx wrangler secret put FCM_SERVICE_ACCOUNT_JSON` for wake pushes,');
  out('  and set SOURCE_URL in wrangler.toml to your fork (AGPL §13).');
}

async function cmdUse(argv) {
  const { flags, rest } = parseFlags(argv);
  const url = rest[0];
  if (!url || !/^https?:\/\//.test(url)) fail('usage: dakflare use <worker-url> --token <admin-token>');
  const token = typeof flags.token === 'string' ? flags.token : loadConfig()?.token;
  if (!token) fail('no admin token: pass --token <admin-token>');

  const probe = await api({ url, token }, 'GET', '/v1/admin/health').catch((e) => ({ status: 0, data: { error: String(e) } }));
  if (probe.status !== 200) {
    fail(`that deployment did not accept the token (HTTP ${probe.status}).\n  ${JSON.stringify(probe.data).slice(0, 200)}`);
  }

  saveConfig({ url, token, installedAt: new Date().toISOString() });
  ok(`configured ${url}`);
  ok(`admin token ${mask(token)} stored at ${CONFIG_FILE} (0600)`);
}

async function cmdDoctor() {
  const cfg = requireConfig();
  const { status, data } = await api(cfg, 'GET', '/v1/admin/health');

  section(`DakFlare doctor — ${cfg.url}`);
  if (status !== 200) {
    warn(`health returned HTTP ${status}`);
    out(`  ${JSON.stringify(data).slice(0, 400)}`);
    process.exit(2);
  }

  out(`  version          ${data.version}`);
  out(`  schema ready     ${data.schema_ready ? 'yes' : 'NO'}`);
  out(`  migrations       ${(data.migrations ?? []).join(', ') || '(none)'}`);
  out(`  retention        ${data.retention_days} days`);
  out(`  counts           devices ${data.counts?.devices ?? '?'} · messages ${data.counts?.messages ?? '?'} · rules ${data.counts?.rules ?? '?'}`);
  out(`  last message     ${data.last_message_at ? new Date(data.last_message_at).toISOString() : '(never)'}`);

  const missing = data.missing_bindings ?? [];
  if (missing.length === 0) ok('all bindings present');
  else if (missing.length === 1 && missing[0] === 'FCM_SERVICE_ACCOUNT') {
    warn('FCM not configured — devices are only reachable while their WebSocket is open');
  } else {
    warn(`missing bindings: ${missing.join(', ')}`);
  }

  if (!data.ok) {
    out('');
    warn('deployment is NOT healthy');
    if (data.db_error) out(`  db error: ${data.db_error}`);
    process.exit(2);
  }
  out('');
  ok('healthy');
}

async function cmdPair(argv) {
  const cfg = requireConfig();
  const { flags } = parseFlags(argv);
  const ttl = Number(flags.ttl ?? 600) * 1000;

  const { status, data } = await api(cfg, 'POST', '/v1/admin/pairing-code', { ttl_ms: ttl });
  if (status !== 200) fail(`could not mint a pairing code (HTTP ${status}): ${JSON.stringify(data).slice(0, 200)}`);

  section('Pair a device');
  out(`  code      ${data.pairing_code}`);
  out(`  expires   ${new Date(data.expires_at).toISOString()}`);
  out('');
  out('  Deep link for the Android app (renders as a QR):');
  out(`  dakflare://pair?u=${encodeURIComponent(cfg.url)}&c=${data.pairing_code}`);
  out('');
  out('  Or enter the URL and code manually in the app.');
}

async function cmdDevices() {
  const cfg = requireConfig();
  const { status, data } = await api(cfg, 'GET', '/v1/devices');
  if (status !== 200) fail(`HTTP ${status}: ${JSON.stringify(data).slice(0, 200)}`);

  const devices = data.devices ?? [];
  section(`Devices (${devices.length})`);
  if (devices.length === 0) {
    out('  no paired devices — run `dakflare pair`');
    return;
  }
  for (const d of devices) {
    const seen = d.last_seen ? new Date(d.last_seen).toISOString() : 'never';
    out(`  ${d.device_id}   last seen ${seen}`);
  }
}

async function cmdSend(argv) {
  const cfg = requireConfig();
  const { flags, rest } = parseFlags(argv);
  const [to, ...bodyParts] = rest;
  const body = bodyParts.join(' ');
  const deviceId = flags.device;

  if (!to || !body) fail('usage: dakflare send <+E164> <message text> --device <device-id>');
  // `POST /v1/sms/send` requires `device_id` today. Fleet/multi-line routing is planned, not
  // implemented — so requiring the flag is honest, rather than pretending a target was chosen.
  if (!deviceId) {
    fail(
      '--device <device-id> is required until fleet routing lands.\n' +
      '  list paired devices with `dakflare devices`.'
    );
  }

  const { status, data } = await api(cfg, 'POST', '/v1/sms/send', { device_id: deviceId, to, body });
  if (status === 200) { ok(`queued ${data.command_id}`); return; }
  if (status === 404 && data?.error === 'device_unknown') {
    fail(`device_unknown — '${deviceId}' is not in the D1 registry.\n  run \`dakflare devices\` to see paired ids.`);
  }
  fail(`HTTP ${status}: ${JSON.stringify(data).slice(0, 200)}`);
}

async function cmdWhoami() {
  section('DakFlare');
  const cfg = loadConfig();
  out(`  target     ${cfg?.url ?? '(not configured)'}`);
  out(`  token      ${cfg?.token ? mask(cfg.token) : '(none)'}`);
  out(`  config     ${CONFIG_FILE}`);
  out('');
  out(`  Cloudflare ${wranglerLoggedIn() ? 'authenticated (wrangler OAuth)' : 'NOT authenticated — run `npx wrangler login`'}`);
}

function cmdHelp() {
  out(`
DakFlare — desktop CLI

  dakflare init [--token <t>] [--url <u>]   install into your Cloudflare account
  dakflare doctor                            health, migrations, bindings
  dakflare pair [--ttl 600]                  mint a pairing code + deep link
  dakflare devices                           list paired devices
  dakflare send <+E164> <text> --device <id> queue an outbound SMS
  dakflare use <url> --token <t>             point at an existing deployment
  dakflare whoami                            show target + auth state

Credentials
  Cloudflare account  wrangler OAuth (owned by Wrangler, never stored here)
  admin API           ADMIN_TOKEN secret, stored 0600 in ~/.config/dakflare/config.json
`);
}

/* ───────────────────────────── main ────────────────────────────── */

const [cmd, ...rest] = process.argv.slice(2);
const COMMANDS = {
  init: cmdInit,
  doctor: cmdDoctor,
  pair: cmdPair,
  devices: cmdDevices,
  send: cmdSend,
  use: cmdUse,
  whoami: cmdWhoami,
  help: cmdHelp,
};

if (!cmd || cmd === '--help' || cmd === '-h') { cmdHelp(); process.exit(0); }
const run = COMMANDS[cmd];
if (!run) { cmdHelp(); fail(`unknown command: ${cmd}`); }

try {
  await run(rest);
} catch (error) {
  fail(String(error?.stack ?? error).slice(0, 600));
}
